/**
 * @file preflight/fixers/fix.seed-diagrams.ts
 * @description Seed Mermaid diagram files
 */

import fs from 'fs';
import path from 'path';
import { registry } from '../engine/registry.js';
import type { Fixer, CheckResult, CheckContext, FixResult } from '../types.js';

const C4_CONTEXT_TEMPLATE = `%% C4 Context Diagram - DevPulse Desktop
%% Generated by preflight system

graph TB
    subgraph Users
        User[User]
    end

    subgraph DevPulse["DevPulse Desktop"]
        App[Desktop App<br/>SvelteKit + Tauri]
    end

    subgraph External["External Systems"]
        API[Backend API]
        DB[(Database)]
    end

    User --> App
    App --> API
    API --> DB

    classDef user fill:#08427b,stroke:#052e56,color:#fff
    classDef system fill:#1168bd,stroke:#0b4884,color:#fff
    classDef external fill:#999999,stroke:#666666,color:#fff

    class User user
    class App system
    class API,DB external
`;

const CORE_FLOW_TEMPLATE = `%% Core Data Flow Diagram
%% Generated by preflight system

flowchart LR
    subgraph Routes["Route Layer"]
        R["+page.svelte"]
    end

    subgraph Domains["Domain Layer"]
        P[Page Component]
        S[State Module]
        SVC[Service]
    end

    subgraph System["System Layer"]
        REG[Registry]
        STR[Streams]
    end

    R --> P
    P --> S
    P --> SVC
    SVC --> REG
    S --> STR

    style R fill:#e1f5fe
    style P fill:#b3e5fc
    style S fill:#81d4fa
    style SVC fill:#4fc3f7
    style REG fill:#29b6f6
    style STR fill:#03a9f4
`;

const diagramsFixer: Fixer = {
  id: 'fix.seed-diagrams',
  name: 'Diagram Seeder',
  description: 'Create Mermaid diagram files',

  canFix(result: CheckResult): boolean {
    return result.message.includes('diagram') ||
      result.message.includes('mermaid') ||
      result.message.includes('.mmd');
  },

  async preview(result: CheckResult, ctx: CheckContext): Promise<FixResult> {
    const diagramsDir = path.join(ctx.targetRoot, 'docs/diagrams');

    // Check which diagrams are missing
    const c4Path = path.join(diagramsDir, 'c4-context.mmd');
    const flowPath = path.join(diagramsDir, 'core-flow.mmd');

    const missing: { path: string; content: string; name: string }[] = [];

    if (!fs.existsSync(c4Path)) {
      missing.push({ path: c4Path, content: C4_CONTEXT_TEMPLATE, name: 'C4 Context' });
    }
    if (!fs.existsSync(flowPath)) {
      missing.push({ path: flowPath, content: CORE_FLOW_TEMPLATE, name: 'Core Flow' });
    }

    if (missing.length === 0) {
      return {
        fixId: 'fix.seed-diagrams',
        file: diagramsDir.replace(ctx.platformRoot, ''),
        applied: false,
        description: 'All diagram files already exist',
      };
    }

    return {
      fixId: 'fix.seed-diagrams',
      file: missing[0].path.replace(ctx.platformRoot, '').replace(/^[/\\]/, ''),
      applied: false,
      description: `Create ${missing.length} diagram(s): ${missing.map(m => m.name).join(', ')}`,
      diff: missing[0].content,
    };
  },

  async apply(result: CheckResult, ctx: CheckContext): Promise<FixResult> {
    const diagramsDir = path.join(ctx.targetRoot, 'docs/diagrams');

    if (!fs.existsSync(diagramsDir)) {
      fs.mkdirSync(diagramsDir, { recursive: true });
    }

    const created: string[] = [];

    const c4Path = path.join(diagramsDir, 'c4-context.mmd');
    if (!fs.existsSync(c4Path)) {
      fs.writeFileSync(c4Path, C4_CONTEXT_TEMPLATE);
      created.push('c4-context.mmd');
    }

    const flowPath = path.join(diagramsDir, 'core-flow.mmd');
    if (!fs.existsSync(flowPath)) {
      fs.writeFileSync(flowPath, CORE_FLOW_TEMPLATE);
      created.push('core-flow.mmd');
    }

    return {
      fixId: 'fix.seed-diagrams',
      file: diagramsDir.replace(ctx.platformRoot, '').replace(/^[/\\]/, ''),
      applied: created.length > 0,
      description: created.length > 0
        ? `Created: ${created.join(', ')}`
        : 'No diagrams created',
    };
  },
};

registry.registerFixer(diagramsFixer);

export { diagramsFixer };
